import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAY_LABELS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

const monthFormatter = new Intl.DateTimeFormat('ru-RU', {
  month: 'long',
  year: 'numeric',
});

const fullDateFormatter = new Intl.DateTimeFormat('ru-RU', {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, amount: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount);
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function buildMonthGrid(year: number, month: number): Date[] {
  const firstDay = new Date(year, month, 1);
  const leading = (firstDay.getDay() + 6) % 7;
  const gridStart = addDays(firstDay, -leading);
  return Array.from({ length: 42 }, (_, index) => addDays(gridStart, index));
}

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [internalDate, setInternalDate] = useState<Date>(() => value ?? today);

  const selected = value ? startOfDay(value) : internalDate;

  const [cursor, setCursor] = useState<Date>(() => new Date(selected.getFullYear(), selected.getMonth(), 1));

  const days = useMemo(
    () => buildMonthGrid(cursor.getFullYear(), cursor.getMonth()),
    [cursor],
  );

  const quickOptions = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: addDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: addDays(today, -7) },
    ],
    [today],
  );

  const selectDate = (date: Date) => {
    const next = startOfDay(date);
    setInternalDate(next);
    setCursor(new Date(next.getFullYear(), next.getMonth(), 1));
    onChange(next);
  };

  const shiftMonth = (amount: number) => {
    setCursor((current) => new Date(current.getFullYear(), current.getMonth() + amount, 1));
  };

  return (
    <section
      className="jx-card jx-stack"
      aria-label="Дата отчёта"
      style={{ display: 'grid', gap: 'var(--jx-space-4)', padding: 'var(--jx-space-4)' }}
    >
      <div
        className="jx-row"
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {quickOptions.map((option) => (
          <Button
            key={option.id}
            type="button"
            className="jx-btn"
            aria-pressed={isSameDay(selected, option.date)}
            onClick={() => selectDate(option.date)}
          >
            {option.label}
          </Button>
        ))}
      </div>

      <div
        className="jx-row"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-2)',
        }}
      >
        <Button type="button" className="jx-btn" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
          ←
        </Button>
        <strong
          aria-live="polite"
          style={{ color: 'var(--jx-fg)', fontSize: 'var(--jx-font-size-md)' }}
        >
          {monthFormatter.format(cursor)}
        </strong>
        <Button type="button" className="jx-btn" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
          →
        </Button>
      </div>

      <div
        role="grid"
        aria-label={`Календарь, ${monthFormatter.format(cursor)}`}
        style={{ display: 'grid', gap: 'var(--jx-space-2)' }}
      >
        <div
          role="row"
          style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 'var(--jx-space-1)' }}
        >
          {WEEKDAY_LABELS.map((label) => (
            <span
              key={label}
              role="columnheader"
              style={{
                color: 'var(--jx-fg-muted)',
                fontSize: 'var(--jx-font-size-sm)',
                textAlign: 'center',
              }}
            >
              {label}
            </span>
          ))}
        </div>

        <div
          role="row"
          style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 'var(--jx-space-1)' }}
        >
          {days.map((day) => {
            const outsideMonth = day.getMonth() !== cursor.getMonth();
            const isSelected = isSameDay(day, selected);
            return (
              <Button
                key={day.toISOString()}
                type="button"
                role="gridcell"
                className="jx-btn"
                aria-label={fullDateFormatter.format(day)}
                aria-selected={isSelected}
                aria-current={isSameDay(day, today) ? 'date' : undefined}
                onClick={() => selectDate(day)}
                style={{ opacity: outsideMonth ? 'var(--jx-opacity-muted, 0.45)' : undefined }}
              >
                {day.getDate()}
              </Button>
            );
          })}
        </div>
      </div>

      <p style={{ color: 'var(--jx-fg-muted)', fontSize: 'var(--jx-font-size-sm)', margin: 0 }}>
        Выбрана дата: {fullDateFormatter.format(selected)}
      </p>
    </section>
  );
}

